+        return new Price(2, total, PriceCalculator.cents(BigDecimal.ZERO), total);
+    }
+
+    @Override
+    public BigDecimal refund(BigDecimal amountPaid, Price price) {
+        return PriceCalculator.cents(amountPaid.multiply(HALF));
+    }
+}
